public class Solution {
    // SPEC: return the length of the longest run of equal adjacent values
    public static int longestRun(int[] arr) {
        if (arr.length == 0) {
            return 0;
        }
        int best = 1;
        int cur = 1;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] == arr[i - 1]) {
                cur++;
                if (cur > best) {
                    best = cur;
                }
            }
        }
        return best;
    }
}

